  "type": "settle",
  "settlement": {
    "decisions": {
      "assignments": {
        "partner_liaison": "Sgt Malik",
        "pol_accountability": "Cpl Ortiz",
        "movement_control": "Spc Vega"
      }
    },
    "credited_facts": [
      "PF1",
      "PF2",
      "PF3"
    ],
    "commitments": [
      {
        "type": "administrative",
        "target": "1st Lt. Nguyen",
        "detail": "Ensure Sgt Malik's updated host-nation language qualification is reflected on the S-3 briefing slide before the roster is published."
      },
      {
        "type": "administrative",
        "target": "SFC Alvarez",
        "detail": "Ensure Cpl Ortiz's POL and hazardous-material accountability inspection update is entered in the roster tracker before the roster is published."
      },
      {
        "type": "administrative",
        "target": "Lt. Brooks",
        "detail": "Ensure Spc Vega's movement-control-system operator renewal notice is attached to the exercise tasking order before the roster is published."
      }
    ],
    "justification_fact_ids": [
      "PF1",
      "PF2",
      "PF3"
    ]
  }
}
```

